
#pragma once

#include <stddef.h>
#include <inttypes.h>

#include "base.c"


typedef uint64_t ImplicState[16];

// the full implication state generated by the rule
static ImplicState full_implic_state;

// these return the implic state mask for where the cell
// at position pos in the 10-bit state is unknown, off, or on, respectively
static ImplicState IMPLICSTATE_CELL_MASKS[10][3];

// IMPLICSTATE_PAIR_SAME_MASKS[pos1][pos2] returns the implic state mask for
// where the cells at position pos1 and pos2 have the same value
// and IMPLICSTATE_PAIR_DIFFERENT_MASKS is the same thing but the cell values must be different
static ImplicState IMPLICSTATE_PAIR_SAME_MASKS[10][10];
static ImplicState IMPLICSTATE_PAIR_DIFFERENT_MASKS[10][10];


static inline int implicstate_get_bit(ImplicState state, int bit) {
    return (state[bit >> 6] >> (bit & 63)) & 1;
}

static inline void implicstate_set_bit(ImplicState state, int bit, int value) {
    if (value == 0) {
        state[bit >> 6] &= ~((uint64_t)1 << (bit & 63));
    } else {
        state[bit >> 6] |= ((uint64_t)1 << (bit & 63));
    }
}

static inline void implicstate_and(ImplicState x, ImplicState y) {
    for (int i = 0; i < 16; i++) {
        x[i] &= y[i];
    }
}

[[maybe_unused]] static void print_implicstate(ImplicState state) {
    printf("Implication state:\n");
    int k = 0;
    for (int i = 0; i < 16; i++) {
        print_line_padding();
        for (int j = 0; j < 64; j++) {
            real_printf("%i", implicstate_get_bit(state, k));
            k++;
        }
        real_printf("\n");
    }
}

static void init_implicstate_masks(void) {
    for (int i = 0; i < 512; i++) {
        if (state.trs[i]) {
            implicstate_set_bit(full_implic_state, i << 1, 0);
            implicstate_set_bit(full_implic_state, (i << 1) | 1, 1);
        } else {
            implicstate_set_bit(full_implic_state, i << 1, 1);
            implicstate_set_bit(full_implic_state, (i << 1) | 1, 0);
        }
    }
    debug(4, print_implicstate(full_implic_state));
    for (int pos = 0; pos < 10; pos++) {
        for (int i = 0; i < 16; i++) {
            IMPLICSTATE_CELL_MASKS[pos][0][i] = UINT64_MAX;
        }
        for (int i = 0; i < 1024; i++) {
            implicstate_set_bit(IMPLICSTATE_CELL_MASKS[pos][convert_01_to_12((i >> pos) & 1)], i, 1);
        }
    }
    for (int pos1 = 0; pos1 < 10; pos1++) {
        for (int pos2 = 0; pos2 < 10; pos2++) {
            for (int i = 0; i < 1024; i++) {
                if ((i >> pos1) == (i >> pos2)) {
                    implicstate_set_bit(IMPLICSTATE_PAIR_SAME_MASKS[pos1][pos2], i, 1);
                } else {
                    implicstate_set_bit(IMPLICSTATE_PAIR_DIFFERENT_MASKS[pos1][pos2], i, 1);
                }
            }
        }
    }
}

// implication bytecode format:
// 6 bit instructions, packed where the first instructions to execute are lower in significance
// instruction format: 0bvvpppp
// where v is the value to set it to, and p is the position index
// this only uses up instructions starting with 01 or 10
// so instruction 000000 is do nothing and stop (there are no further instructions)
// and instruction 000001 means there is a contradiction
// position order:
//     0: next
//     1: se
//     2: e
//     3: ne
//     4: s
//     5: c
//     6: n
//     7: sw
//     8: w
//     9: nw
// this matches the order inside the `Clause` type!

// array of 59049 uint64_t's containing implication bytecode
uint64_t* implication_table;

static uint64_t get_implications_for_tr(uint32_t tr) {
    CellValue next = (tr / 1) % 3;
    CellValue se = (tr / 3) % 3;
    CellValue e = (tr / 9) % 3;
    CellValue ne = (tr / 27) % 3;
    CellValue s = (tr / 81) % 3;
    CellValue c = (tr / 243) % 3;
    CellValue n = (tr / 729) % 3;
    CellValue sw = (tr / 2187) % 3;
    CellValue w = (tr / 6561) % 3;
    CellValue nw = (tr / 19683) % 3;
    CellValue cells[10] = {next, se, e, ne, s, c, n, sw, w, nw};
    ImplicState state;
    memcpy(state, full_implic_state, sizeof(ImplicState));
    implicstate_and(state, IMPLICSTATE_CELL_MASKS[0][next]);
    implicstate_and(state, IMPLICSTATE_CELL_MASKS[1][se]);
    implicstate_and(state, IMPLICSTATE_CELL_MASKS[2][e]);
    implicstate_and(state, IMPLICSTATE_CELL_MASKS[3][ne]);
    implicstate_and(state, IMPLICSTATE_CELL_MASKS[4][s]);
    implicstate_and(state, IMPLICSTATE_CELL_MASKS[5][c]);
    implicstate_and(state, IMPLICSTATE_CELL_MASKS[6][n]);
    implicstate_and(state, IMPLICSTATE_CELL_MASKS[7][sw]);
    implicstate_and(state, IMPLICSTATE_CELL_MASKS[8][w]);
    implicstate_and(state, IMPLICSTATE_CELL_MASKS[9][nw]);
    uint64_t out = 0;
    for (int pos = 0; pos < 10; pos++) {
        uint64_t* mask_0 = IMPLICSTATE_CELL_MASKS[pos][OFF];
        uint64_t* mask_1 = IMPLICSTATE_CELL_MASKS[pos][ON];
        uint64_t any_can_be_0 = 0;
        uint64_t any_can_be_1 = 0;
        for (int i = 0; i < 16; i++) {
            any_can_be_0 |= (state[i] & mask_0[i]);
            any_can_be_1 |= (state[i] & mask_1[i]);
        }
        bool can_be_0 = any_can_be_0 != 0;
        bool can_be_1 = any_can_be_1 != 0;
        if (!can_be_0 && !can_be_1) {
            // contradiction;
            return 1;
        } else if (!can_be_0 && can_be_1) {
            if (cells[pos] == UNKNOWN) {
                out <<= 6;
                out |= (ON << 4) | pos;
            }
        } else if (can_be_0 && !can_be_1) {
            if (cells[pos] == UNKNOWN) {
                out <<= 6;
                out |= (OFF << 4) | pos;
            }
        } else {
            // do nothing
        }
    }
    return out;
}

static void init_implications(void) {
    init_implicstate_masks();
    implication_table = safe_malloc(59049 * sizeof(uint64_t));
    for (uint32_t tr = 0; tr < 59049; tr++) {
        implication_table[tr] = get_implications_for_tr(tr);
    }
}

static void destroy_implications(void) {
    safe_free(implication_table);
}


static bool set_cell(Cell* cell, CellValue value) {
    debug(4, printf("Setting cell: variable = %zu, value = %i, prev_value = %i\n", cell->var_number, value, cell->value));
    cell->value = value;
    #define update(clause, value) \
        if ((clause) != NULL) { \
            (clause)->implication_tr += UINT32_C(value); \
        }
    if (value == OFF) {
        for (size_t i = 0; i < cell->use_count; i++) {
            CellUseData* data = &(cell->uses[i]);
            update(data->prev, 1);
            update(data->nw, 3);
            update(data->w, 9);
            update(data->sw, 27);
            update(data->n, 81);
            update(data->c, 243);
            update(data->s, 729);
            update(data->ne, 2187);
            update(data->e, 6561);
            update(data->se, 19683);
        }
    } else {
        for (size_t i = 0; i < cell->use_count; i++) {
            CellUseData* data = &(cell->uses[i]);
            update(data->prev, 2);
            update(data->nw, 6);
            update(data->w, 18);
            update(data->sw, 54);
            update(data->n, 162);
            update(data->c, 486);
            update(data->s, 1458);
            update(data->ne, 4374);
            update(data->e, 13122);
            update(data->se, 39366);
        }
    }
    #undef update
    return true;
}

static void unset_cell(Cell* cell) {
    debug(4, printf("Unsetting variable %zu: prev_value = %i\n", cell->var_number, cell->value));
    #define update(clause, value) \
        if ((clause) != NULL) { \
            (clause)->implication_tr += INT32_C(value); \
        }
    if (cell->value == OFF) {
        for (size_t i = 0; i < cell->use_count; i++) {
            CellUseData* data = &(cell->uses[i]);
            update(data->prev, -1);
            update(data->nw, -3);
            update(data->w, -9);
            update(data->sw, -27);
            update(data->n, -81);
            update(data->c, -243);
            update(data->s, -729);
            update(data->ne, -2187);
            update(data->e, -6561);
            update(data->se, -19683);
        }
    } else {
        for (size_t i = 0; i < cell->use_count; i++) {
            CellUseData* data = &(cell->uses[i]);
            update(data->prev, -2);
            update(data->nw, -6);
            update(data->w, -18);
            update(data->sw, -54);
            update(data->n, -162);
            update(data->c, -486);
            update(data->s, -1458);
            update(data->ne, -4374);
            update(data->e, -13122);
            update(data->se, -39366);
        }
    }
    #undef update
    cell->value = UNKNOWN;
}

static void init_clause_implication_tr(Clause* clause) {
    clause->implication_tr = 0
        + (clause->next->value * 1)
        + (clause->se->value * 3)
        + (clause->e->value * 9)
        + (clause->ne->value * 27)
        + (clause->s->value * 81)
        + (clause->c->value * 243)
        + (clause->n->value * 729)
        + (clause->sw->value * 2187)
        + (clause->w->value * 6561)
        + (clause->nw->value * 19683)
    ;
    debug(4, printf("Transition for clause %zu: %"PRIu32"\n", clause->number, clause->implication_tr));
}


// stack of clauses to check in set_cell_and_propagate
Clause** clause_stack;
// stack pointer for `clause_stack`
Clause** clause_sp;
// stack pointer for the done entries of clause_stack
Clause** clause_done_sp;

static void init_clause_stack(void) {
    clause_stack = safe_malloc(16384 * sizeof(Clause*));
}

static void destroy_clause_stack(void) {
    safe_free(clause_stack);
}

static inline bool internal_clause_set_cell(Cell* cell, CellValue value, bool is_explicit) {
    // maybe manually inline and optimize the set_cell_and_push?
    // could be faster? depends on how clever the compiler is
    if (!set_cell_and_push(cell, value, is_explicit)) {
        return false;
    }
    for (size_t i = 0; i < cell->use_count; i++) {
        CellUseData* data = &(cell->uses[i]);
        #define add(clause) \
            if ((clause) != NULL) { \
                *clause_sp = (clause); \
                clause_sp++; \
            }
        add(data->c);
        add(data->prev);
        add(data->nw);
        add(data->w);
        add(data->sw);
        add(data->n);
        add(data->s);
        add(data->ne);
        add(data->e);
        add(data->se);
        #undef add
    }
    return true;
}

// returns false if contradiction, true if no contradiction
static inline bool check_implications(Clause* clause) {
    uint64_t code = implication_table[clause->implication_tr];
    debug(4, printf("Implication for clause %zu: transition = %"PRIu32", code = %"PRIu64"\n", clause->number, clause->implication_tr, code));
    if (code == 1) {
        debug(3, printf("Contradiction in check_implications\n"));
        return false;
    }
    while (code != 0) {
        int instruction = ((int)code) & 63;
        int cell_pos = instruction & 15;
        CellValue value = instruction >> 4;
        // i think this is undefined behavior, but it should work in most cases
        Cell* cell = *(Cell**)(((char*)clause) + offsetof(Clause, next) + cell_pos * (offsetof(Clause, se) - offsetof(Clause, next)));
        if (!internal_clause_set_cell(cell, value, false)) {
            return false;
        }
        code >>= 6;
    }
    return true;
}

// set a cell in the search state, propagating checks
// returns false if contradiction, true if no contradiction
static bool set_cell_and_propagate(Cell* cell, CellValue value, bool is_explicit) {
    debug(3, printf("Setting cell and propagating: var_number = %zu\n", cell->var_number));
    clause_sp = &(clause_stack[0]);
    clause_done_sp = &(clause_stack[0]);
    if (!internal_clause_set_cell(cell, value, is_explicit)) {
        return false;
    }
    while (clause_done_sp < clause_sp) {
        debug(3, printf("Propagating: clause_sp = %ti, clause_done_sp = %ti\n", clause_sp - &(clause_stack[0]), clause_done_sp - &(clause_stack[0])));
        debug(5, print_grid(stdout));
        if (!check_implications(*clause_done_sp)) {
            return false;
        }
        clause_done_sp++;
    }
    return true;
}
